import './style.css';

import * as React from 'react';

import { cn } from '@/lib/utils';

/*
 * @author: @joao-carmassi
 * @description: Ambient aura wrapper that projects a conic-gradient glow around any component.
 * Wrap any Card (or element) with <AuraBeam> to get a diffuse, rotating light effect inspired by daisyUI's Aura.
 * Combine with .aura-beam-rainbow, .aura-beam-holo, and .aura-beam-glow modifier classes.
 * @version: 1.0.0
 * @date: 2026-06-07
 * @license: MIT
 */

interface AuraBeamProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The content to wrap with the aura effect.
   */
  children: React.ReactNode;
}

export function AuraBeam({
  className,
  children,
  ...props
}: AuraBeamProps): React.ReactNode {
  return (
    <div className={cn('aura-beam', className)} {...props}>
      {children}
    </div>
  );
}

[data-variant='default'] {
  --pulse-color: var(--primary);
}
[data-variant='destructive'] {
  --pulse-color: var(--destructive);
}
[data-variant='secondary'] {
  --pulse-color: var(--secondary-foreground);
}
[data-variant='outline'] {
  --pulse-color: var(--ring);
}
[data-variant='ghost'] {
  --pulse-color: var(--ring);
}

.before\:animate-shine-effect::before {
  animation: shine-effect 3s ease-out infinite;
}

.animate-rainbow-effect {
  animation: rainbow-effect 3s linear infinite;
}

.animate-pulsating-effect {
  animation: pulsating-effect 1.5s ease-out infinite;
}

.card-shine-effect {
  animation: card-shine-effect var(--duration) infinite linear;
}

@keyframes shine-effect {
  0% {
    background-position: 200% 0;
  }
  25% {
    background-position: -200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes rainbow-effect {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes pulsating-effect {
  0% {
    box-shadow: 0 0 0 0 var(--pulse-color, currentColor);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes card-shine-effect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

/* ─── Aura Beam ─────────────────────────────────────────────────────────── */

@property --aura-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes aura-spin {
  to {
    --aura-angle: 360deg;
  }
}

.aura-beam {
  --aura-padding: 2px;
  --aura-radius: 0.75rem;
  --aura-duration: 6s;
  --aura-color: hsl(var(--primary));

  position: relative;
  display: inline-block;
  padding: var(--aura-padding);
  border-radius: calc(var(--aura-radius) + var(--aura-padding));
  color: var(--aura-color);

  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 220deg,
    currentColor 280deg,
    currentColor 360deg
  );

  animation: aura-spin var(--aura-duration) linear infinite;
}

.aura-beam > * {
  position: relative;
  z-index: 2;
  border-radius: var(--aura-radius);
}

.aura-beam::before,
.aura-beam::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  pointer-events: none;
  z-index: 0;
}

.aura-beam::before {
  filter: blur(6px);
  opacity: 0.65;
}

.aura-beam::after {
  filter: blur(18px);
  opacity: 0.35;
}

.aura-beam-rainbow {
  background-image: conic-gradient(
    from var(--aura-angle),
    #ef4444,
    #f97316,
    #eab308,
    #22c55e,
    #06b6d4,
    #3b82f6,
    #a855f7,
    #ef4444
  );
}

.aura-beam-holo {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    #22d3ee 60deg,
    #a78bfa 140deg,
    #f0abfc 220deg,
    #67e8f9 300deg,
    transparent 360deg
  );
}

.aura-beam-glow::before {
  filter: blur(10px);
  opacity: 0.8;
}

.aura-beam-glow::after {
  filter: blur(28px);
  opacity: 0.55;
}
